    "配对后可操作这台电脑的 Agent、项目、Git 和终端，并查看、控制电脑屏幕。你可以随时在电脑上撤销授权。": "ペアリングすると、この PC の Agent、プロジェクト、Git、ターミナルを操作し、PC の画面を表示・操作できます。許可は PC からいつでも取り消せます。",
