    "无法核实电脑上的项目，请重新连接后再试。": "PC 上のプロジェクトを確認できません。再接続して再試行してください。",
    "请更新电脑端后再操作，尚未启动或修改配置。": "先に PC のアプリを更新してください。構成はまだ起動・変更されていません。",
    "原启动回执不匹配。": "元の起動の受領情報が一致しません。",
    "原启动记录与项目或运行配置不匹配，未重新执行。": "元の起動記録がプロジェクトまたは実行構成と一致しないため、再実行していません。",
    "运行配置回执与原操作不匹配，请更新电脑端后核实。": "実行構成の受領情報が元の操作と一致しません。PC のアプリを更新してから確認してください。",
    "电脑没有返回可确认的运行配置结果，请核实原操作。": "PC から確認可能な実行構成の結果が返されませんでした。元の操作を確認してください。",
    "运行配置操作未完成，请核实。": "実行構成の操作が完了していません。確認してください。",
    "没有待核实的启动操作。": "確認待ちの起動操作はありません。",
    "电脑未确认原启动已关闭，记录仍保留。": "PC は元の起動が閉じられたことを確認していません。記録は残っています。",
    "原启动结果尚未确认，记录仍保留。": "元の起動結果が未確認です。記録は残っています。",
    "服务地址必须使用 HTTPS；调试版本可使用本机或局域网 IP。": "サービスのアドレスには HTTPS を使用する必要があります。デバッグ版ではローカルまたは LAN の IP を使用できます。",
    "服务暂时不可用，请稍后重试。": "サービスを一時的に利用できません。しばらくしてから再試行してください。",
    "服务返回了无法识别的响应。": "サービスから認識できない応答が返されました。",
    "无法连接服务，请检查网络和服务地址。": "サービスに接続できません。ネットワークとサービスのアドレスを確認してください。",
    "无法验证服务证书，请检查服务配置。": "サービスの証明書を検証できません。サービスの設定を確認してください。",
    "服务响应无效或连接已中断，请重试。": "サービスの応答が無効か、接続が切れました。再試行してください。",
    "服务版本不兼容，请更新 App 或服务端。": "サービスのバージョンに互換性がありません。App またはサーバーを更新してください。",
    "二维码内容过长。": "QR コードの内容が長すぎます。",
    "不是 DogCodes 配对二维码。": "DogCodes のペアリング用 QR コードではありません。",
    "配对二维码无效，或来自未配置的服务。": "ペアリング用 QR コードが無効か、未設定のサービスのものです。",
    "配对二维码已过期，请在电脑上重新生成。": "ペアリング用 QR コードの有効期限が切れました。PC で再生成してください。",
    "设备时间不一致，请校准手机和电脑时间后重试。": "デバイスの時刻が一致しません。スマホと PC の時刻を合わせて再試行してください。",
    "无法读取配对二维码。": "ペアリング用 QR コードを読み取れません。",
    "事件游标格式无效。": "イベントカーソルの形式が無効です。",
    "事件游标超出范围。": "イベントカーソルが範囲外です。",
    "电脑离线，重新连接后再浏览目录。": "PC はオフラインです。再接続してからディレクトリを閲覧してください。",
    "连接已更换，请重新读取目录。": "接続が切り替わりました。ディレクトリを再読み込みしてください。",
    "电脑未返回有效的目录列表，请更新电脑端后重试。": "PC から有効なディレクトリ一覧が返されませんでした。PC のアプリを更新して再試行してください。",
    "目录分页没有前进，请刷新目录。": "ディレクトリのページ送りが進みませんでした。ディレクトリを更新してください。",
    "电脑端暂不支持目录选择，请更新电脑端后重试。": "PC のアプリはディレクトリの選択に未対応です。PC のアプリを更新して再試行してください。",
    "剪贴板传输响应无效": "クリップボード転送の応答が無効です",
    "剪贴板传输身份不匹配": "クリップボード転送の ID が一致しません",
    "剪贴板传输校验信息不匹配": "クリップボード転送の検証情報が一致しません",
    "图片需小于 16 MB，请缩小图片后重试": "画像は 16 MB 未満にしてください。縮小して再試行してください",
    "剪贴板文字为空或超过 1 MB": "クリップボードのテキストが空か、1 MB を超えています",
    "图片传输起始位置无效": "画像転送の開始位置が無効です",
    "剪贴板上传位置不匹配": "クリップボードのアップロード位置が一致しません",
    "尚未确认电脑剪贴板是否更新，请从电脑获取核实；不会自动重发": "PC のクリップボードが更新されたか未確認です。PC から取得して確認してください。自動で再送はしません",
    "未确认电脑剪贴板已更新，请从电脑获取核实；不会自动重发": "PC のクリップボードの更新が確認できていません。PC から取得して確認してください。自動で再送はしません",
    "剪贴板写入回执不完整，请从电脑获取核实": "クリップボードの書き込みの受領情報が不完全です。PC から取得して確認してください",
    "剪贴板下载数据块过大": "クリップボードのダウンロードのデータブロックが大きすぎます",
    "剪贴板下载位置不匹配": "クリップボードのダウンロード位置が一致しません",
    "剪贴板内容校验失败，未写入手机剪贴板": "クリップボードの内容の検証に失敗したため、スマホのクリップボードには書き込んでいません",
    "通知服务初始化失败。": "通知サービスの初期化に失敗しました。",
    "此版本未配置备用通知服务。": "このビルドではバックアップの通知サービスが設定されていません。",
    "系统通知权限尚未开启。": "システムの通知権限が有効になっていません。",
    "任务提醒": "タスクの通知",
    "待审批、待回答、完成和失败提醒": "承認待ち、回答待ち、完了、失敗の通知",
    "未获取到通知设备身份。": "通知用のデバイス ID を取得できませんでした。",
    "这台电脑已移除，未发送停止请求。": "この PC は削除されたため、停止リクエストは送信されていません。",
    "这个任务已经有一个停止请求在等待确认。": "このタスクにはすでに確認待ちの停止リクエストがあります。",
    "等待确认的停止请求太多，请先处理待处理页里的卡片。": "確認待ちの停止リクエストが多すぎます。先に対応待ちページのカードを処理してください。",
    "任务当前没有可停止的运行。": "このタスクには停止できる実行がありません。",
    "暂时无法读取任务状态，请稍后再确认。": "タスクの状態を読み取れません。しばらくしてから確認してください。",
    "这台电脑已移除，未重新发送停止请求。": "この PC は削除されたため、停止リクエストは再送されていません。",
    "原停止请求已改变，请刷新。": "元の停止リクエストが変更されました。更新してください。",
    "没有待确认的停止请求。": "確認待ちの停止リクエストはありません。",
    "电脑已收到停止请求，任务会在停下后更新状态。": "PC は停止リクエストを受信しました。タスクが停止すると状態が更新されます。",
    "这次运行已经结束，不需要再停止。": "この実行はすでに終了しています。停止する必要はありません。",
    "已不再等待。如果电脑收到了这个停止请求，任务仍会停下。": "待機を停止しました。PC がこの停止リクエストを受信していれば、タスクは停止します。",
    "还不确定是否已停止，可以再发一次停止。": "停止したかどうかはまだわかりません。もう一度停止を送信できます。",
    "附件总大小不能超过 25 MB。": "添付ファイルの合計サイズは 25 MB を超えられません。",
    "附件文件名过长或无效。": "添付ファイル名が長すぎるか無効です。",
    "图片请使用 PNG、JPEG、GIF 或 WebP 格式。": "画像は PNG、JPEG、GIF、WebP のいずれかの形式にしてください。",
    "一次最多发送 16 个附件。": "一度に送信できる添付ファイルは最大 16 個です。",
    "附件上传已暂停，可继续原上传。": "添付ファイルのアップロードは一時停止中です。元のアップロードを再開できます。",
    "附件回执与原文件不一致，未发送任务。": "添付ファイルの受領情報が元のファイルと一致しないため、タスクは送信されていません。",
    "本机附件内容已变化，请重新添加；未上传变化后的文件。": "このスマホの添付ファイルの内容が変更されました。追加し直してください。変更後のファイルはアップロードされていません。",
    "电脑端暂不支持附件上传，请更新电脑端。": "PC のアプリは添付ファイルのアップロードに未対応です。PC のアプリを更新してください。",
    "电脑返回的附件位置无效。": "PC から返された添付ファイルの位置が無効です。",
    "附件分块位置未确认，请继续原上传。": "添付ファイルの分割位置が未確認です。元のアップロードを再開してください。",
    "原草稿不可读取，请重新选择附件。": "元の下書きを読み取れません。添付ファイルを選び直してください。",
    "上次附件选择未完成，请重新选择。": "前回の添付ファイルの選択が完了していません。選び直してください。",
    "已恢复系统文件选择器返回的附件，请核对后发送。": "システムのファイル選択から返された添付ファイルを復元しました。確認してから送信してください。",
    "附件选择未完成：{0}，请重新选择。": "添付ファイルの選択が完了していません：{0}。選び直してください。",
    "上次附件选择未能恢复：{0}": "前回の添付ファイルの選択を復元できませんでした：{0}",
    "正在处理这台电脑的原配对，请稍后核实。": "この PC の元のペアリングを処理中です。しばらくしてから確認してください。",
    "原配对恢复记录已改变，请刷新后核实。": "元のペアリングの復元記録が変更されました。更新して確認してください。",
    "电脑绑定已移除或变化，请重新配对后连接。": "PC のペアリングが削除または変更されました。ペアリングし直してから接続してください。",
    "未命名会话": "無題のチャット",
    "离线模式": "オフラインモード",
    "离线协作": "オフライン共同作業",
    "部分离线数据暂时无法读取，联网后可重新同步。": "一部のオフラインデータを読み取れません。接続後に再同期できます。",
    "停止请求暂时无法读取，请检查系统安全存储。": "停止リクエストを読み取れません。システムのセキュアストレージを確認してください。",
    "终端关闭记录暂时无法读取，请检查系统安全存储。": "ターミナルを閉じた記録を読み取れません。システムのセキュアストレージを確認してください。",
    "已配对电脑暂时无法读取，请检查系统安全存储。": "ペアリング済みの PC を読み取れません。システムのセキュアストレージを確認してください。",
    "电脑绑定已变化，未使用旧页面接管新的连接。": "PC のペアリングが変更されたため、古いページは新しい接続を引き継いでいません。",
    "连接中断，正在重新连接。已发送操作不会重复执行。": "接続が切れました。再接続しています。送信済みの操作が二重に実行されることはありません。",
    "连接已断开。电脑上的任务不会因此停止。": "切断されました。PC 上のタスクは停止しません。",
    "移除未完成，连接已关闭；请重试移除或核实安全存储。": "削除が完了していません。接続は閉じられました。削除を再試行するか、セキュアストレージを確認してください。",
    "离线缓存未能保存：{0}": "オフラインキャッシュを保存できませんでした：{0}",
    "待确认的操作暂时无法读取，请检查系统安全存储。": "確認待ちの操作を読み取れません。システムのセキュアストレージを確認してください。",
    "无法读取后台提醒设置，请检查系统安全存储后重试。": "バックグラウンド通知の設定を読み取れません。システムのセキュアストレージを確認して再試行してください。",
    "部分电脑的通知尚未登记，请检查网络后重新检测。": "一部の PC の通知が登録されていません。ネットワークを確認して再確認してください。",
    "后台提醒尚未启用，请核实系统通知权限和通知服务配置后重试。": "バックグラウンド通知が有効になっていません。システムの通知権限と通知サービスの設定を確認して再試行してください。",
    "Git 操作已完成": "Git 操作が完了しました",
    "已经提交，还不确定是否推送成功，可以重新发送推送。": "コミットしましたが、プッシュが成功したかは未確認です。プッシュを再送できます。",
    "提交已完成，推送失败：{0}": "コミットは完了しましたが、プッシュに失敗しました：{0}",
    "Git 操作失败：{0}": "Git 操作に失敗しました：{0}",
    "电脑正在执行 Git 操作，稍后再确认。": "PC で Git 操作を実行中です。しばらくしてから確認してください。",
    "Git 操作中途中断了，请在「变更」里看一下仓库现在的状态。": "Git 操作が途中で中断されました。「変更」でリポジトリの現在の状態を確認してください。",
    "Git 操作只完成了一部分，请先在「变更」里看一下再继续。": "Git 操作は一部のみ完了しました。続行する前に「変更」で確認してください。",
    "已不再等待这次 Git 操作。": "この Git 操作の待機を停止しました。",
    "电脑上还查不到这次 Git 操作，可能没收到，可以重新发送。": "PC にこの Git 操作の記録がまだありません。届いていない可能性があるため、再送できます。",
    "还不确定文件是否已暂存，所以没有继续提交。": "ファイルがステージされたか未確認のため、コミットは続行していません。",
    "暂存回执与原文件选择不一致，未重新执行。": "ステージの受領情報が元のファイル選択と一致しないため、再実行していません。",
    "Git 操作无效。": "無効な Git 操作です。",
    "电脑未返回有效的 Git 操作回执。": "PC から有効な Git 操作の受領情報が返されませんでした。",
    "Git 回执与原请求不一致，未继续操作。": "Git の受領情報が元のリクエストと一致しないため、操作を続行していません。",
    "Git 接续记录过长或存在循环，请在电脑上核实。": "Git の継続記録が長すぎるか、ループしています。PC で確認してください。",
    "电脑尚未确认结束原 Git 跟踪。": "PC は元の Git 追跡の終了をまだ確認していません。",
    "待审批": "承認待ち",
    "待回答": "回答待ち",
    "任务完成": "タスク完了",
    "执行失败": "実行に失敗",
    "通知设置响应无效，请重新读取。": "通知設定の応答が無効です。再読み込みしてください。",
    "设备授权已失效，请核实电脑绑定。": "デバイスの許可が無効になりました。PC のペアリングを確認してください。",
    "通知设置已改变，请重新读取后修改。": "通知設定が変更されました。再読み込みしてから編集してください。",
    "操作过于频繁，请稍后重试。": "操作が多すぎます。しばらくしてから再試行してください。",
    "通知服务暂时不可用，请稍后重试。": "通知サービスを一時的に利用できません。しばらくしてから再試行してください。",
    "无法确认通知设置，请检查网络后重新读取。": "通知設定を確認できません。ネットワークを確認して再読み込みしてください。",
    "电脑没有收到这次设置，请再试一次。": "PC はこの設定を受信していません。もう一度お試しください。",
    "电脑返回的保持唤醒状态无效。": "PC から返されたスリープ防止の状態が無効です。",
    "待发送的输入过多，本次未发送，请缩短输入后再试。": "送信待ちの入力が多すぎるため、今回は送信していません。入力を短くして再試行してください。",
    "终端页面已离开，未继续发送输入。": "ターミナルページを離れたため、入力の送信を停止しました。",
    "终端输入回执不匹配": "ターミナル入力の受領情報が一致しません",
    "请更新电脑端后输入；终端输出仍可查看。": "入力するには PC のアプリを更新してください。ターミナルの出力は引き続き表示できます。",
    "终端正在启动，请稍后继续输入。": "ターミナルを起動中です。しばらくしてから入力を続けてください。",
    "原终端当前不可输入，请刷新查看状态。": "元のターミナルは現在入力を受け付けません。更新して状態を確認してください。",
    "终端输入连接已改变，请检查后继续。": "ターミナル入力の接続が変わりました。確認してから続けてください。",
    "输入连接仍在切换，请稍后检查并继续。": "入力の接続はまだ切り替え中です。しばらくしてから確認して続けてください。",
    "上次输入结果待核实，请检查终端输出后再继续。": "前回の入力結果が未確認です。ターミナルの出力を確認してから続けてください。",
    "输入结果尚未确认，请核实或检查终端后继续；不会重发原输入。": "入力結果が未確認です。確認するかターミナルを確かめてから続けてください。元の入力は再送されません。",
    "终端连接中断，输入结果待核实；未发送的队列已丢弃，不会自动重发。": "ターミナルの接続が切れたため、入力結果が未確認です。未送信のキューは破棄され、自動で再送されることはありません。",
    "原输入仍未确认或通道已改变，请检查终端输出后继续；不会重发。": "元の入力が未確認か、チャネルが変わりました。ターミナルの出力を確認してから続けてください。再送はされません。",
    "暂时无法核实输入，请连接后再试；不会重发原输入。": "入力を確認できません。接続後に再試行してください。元の入力は再送されません。",
    "输入连接尚未恢复，请稍后再试。": "入力の接続がまだ復元されていません。しばらくしてから再試行してください。",
    "这台电脑已移除，未发送关闭请求。": "この PC は削除されたため、終了リクエストは送信されていません。",
    "这个终端已经有一个关闭请求在等待确认。": "このターミナルにはすでに確認待ちの終了リクエストがあります。",
    "等待确认的关闭请求太多，请先处理待处理页里的卡片。": "確認待ちの終了リクエストが多すぎます。先に対応待ちページのカードを処理してください。",
    "原终端关闭结果尚未确认，请核实结束后再启动这个运行配置。": "元のターミナルの終了結果が未確認です。終了を確認してからこの実行構成を起動してください。",
    "请更新电脑端后再关闭终端，当前版本无法核实原终端身份。": "ターミナルを閉じるには PC のアプリを更新してください。現在のバージョンでは元のターミナルの身元を確認できません。",
    "终端身份不完整，请刷新后再关闭。": "ターミナルの身元が不完全です。更新してから閉じてください。",
    "终端已经重新启动过，没有关闭新的终端。": "ターミナルは再起動されているため、新しいターミナルは閉じていません。",
    "终端不存在": "ターミナルが存在しません",
    "没有待确认的终端关闭操作。": "確認待ちのターミナル終了操作はありません。",
    "终端已经关闭。": "ターミナルは閉じられました。",
    "已不再等待。如果电脑收到了关闭请求，终端仍会关闭。": "待機を停止しました。PC が終了リクエストを受信していれば、ターミナルは閉じられます。",
    "终端已改变，关闭请求未执行。": "ターミナルが変更されたため、終了リクエストは実行されていません。",
    "电脑已收到关闭请求，正在等终端结束。": "PC は終了リクエストを受信しました。ターミナルの終了を待っています。",
    "还不确定终端是否已关闭，可以稍后再确认。": "ターミナルが閉じられたかはまだわかりません。しばらくしてから確認してください。",
    "请选择有效的审查问题。": "有効なレビューの問題を選択してください。",
    "审查回执与原请求不匹配，请保留原操作并核实。": "レビューの受領情報が元のリクエストと一致しません。元の操作を残して確認してください。",
    "修复回执与原请求不匹配，请先核实电脑上的原修复。": "修正の受領情報が元のリクエストと一致しません。先に PC 上の元の修正を確認してください。",
    "无法读取审查记录，请更新电脑端后重试。": "レビューの記録を読み取れません。PC のアプリを更新して再試行してください。",
    "消息分片取消标识无效。": "メッセージ分割のキャンセルフラグが無効です。",
    "消息大小超出范围。": "メッセージのサイズが範囲外です。",
    "二进制消息格式无效。": "バイナリメッセージの形式が無効です。",
    "消息分片格式无效。": "メッセージ分割の形式が無効です。",
    "消息分片顺序或数量无效。": "メッセージ分割の順序または数が無効です。",
    "消息分片不连续。": "メッセージの分割が連続していません。",
    "消息分片长度无效。": "メッセージ分割の長さが無効です。",
    "不允许嵌套消息分片。": "メッセージ分割の入れ子は許可されていません。",
    "会话版本不可用，请刷新后重试。": "チャットのバージョンを利用できません。更新して再試行してください。",
    "会话名称需为 1–120 个字符，且不能包含控制字符。": "チャット名は 1～120 文字で、制御文字を含めることはできません。",
    "会话状态无效。": "チャットの状態が無効です。",
    "无法读取电脑的会话设置，请更新电脑端后重试。": "PC のチャット設定を読み取れません。PC のアプリを更新して再試行してください。",
    "Fork 环境无效。": "Fork の環境が無効です。",
    "Fork 返回的会话身份不一致，请核实原操作。": "Fork から返されたチャットの身元が一致しません。元の操作を確認してください。",
    "没有待确认的会话操作。": "確認待ちのチャット操作はありません。",
    "原操作已变化，请刷新。": "元の操作が変更されました。更新してください。",
    "Fork 回执与原请求不一致。": "Fork の受領情報が元のリクエストと一致しません。",
    "这项操作需要先核实结果。": "この操作は先に結果を確認する必要があります。",
    "这台电脑已移除，未再发送请求。": "この PC は削除されたため、リクエストは再送されていません。",
    "原电脑记录尚未清理完成，请重试移除电脑后再连接。": "元の PC の記録の削除が完了していません。PC の削除を再試行してから接続してください。",
    "电脑绑定已变化，未发送原操作；请重新连接后确认。": "PC のペアリングが変更されたため、元の操作は送信されていません。再接続してから確認してください。",
    "原操作已结束或已更新，请刷新后操作。": "元の操作は終了したか更新されました。更新してから操作してください。",
    "中继连接中断，操作结果需要核实。": "リレーの接続が切れました。操作結果を確認する必要があります。",
    "中继探针仅供本地开发使用。": "リレープローブはローカル開発専用です。",
    "数据帧大小超出范围。": "データフレームのサイズが範囲外です。",
    "连接已关闭；操作结果需要核实。": "接続が閉じられました。操作結果を確認する必要があります。",
