    "此项目不是 Git 仓库，分叉只继承对话上下文，并沿用同一项目目录。": "このプロジェクトは Git リポジトリではないため、分岐は会話のみを引き継ぎ、同じプロジェクトフォルダで続行します。",
    "此会话由旧版分叉创建，未恢复历史轮次的文件。": "この会話は旧バージョンの分岐で作成されたため、ターンのファイルは復元されていません。",
