    "这个项目还没有会话。电脑以会话为单位授权工作区访问，请先在项目中开始一个会话。": "이 프로젝트에는 아직 대화가 없습니다. 작업 공간 접근은 대화 단위로 허용되므로 먼저 프로젝트에서 대화를 시작하세요.",
