    "已找到电脑上的原终端，可在终端或运行页面继续查看；未重新运行命令。": "컴퓨터에서 원래 터미널을 찾았습니다. 터미널 또는 실행 페이지에서 계속 볼 수 있습니다. 명령은 다시 실행되지 않았습니다.",
    "分析已经开始，可在运行页面查看进度。": "분석을 시작했습니다. 실행 페이지에서 진행 상황을 확인하세요.",
