    "从不弹出确认；只运行预先允许和安全的只读操作，其余一律拒绝。": "확인 창을 표시하지 않습니다. 사전 허용된 안전한 읽기 작업만 실행하고 나머지는 거부합니다.",
    "Pi 不内置逐工具审批或沙箱；工具直接执行，扩展发起的询问会显示在对话中。": "Pi에는 도구별 승인이나 샌드박스가 없습니다. 도구는 바로 실행되며 확장 프로그램의 질문은 대화에 표시됩니다.",
