    "监督模式：工具操作前请求审批。": "감독 모드: 도구 작업 전에 승인을 요청합니다.",
    "由 ZCode 判断哪些操作可直接执行。": "어떤 작업을 바로 실행할지 ZCode가 판단합니다.",
