    "由 AI 审查员批准或拒绝原本需要询问的操作；审查失败只阻止该操作。": "원래 확인이 필요한 작업을 AI 검토자가 승인하거나 거부합니다. 검토에 실패하면 해당 작업만 차단됩니다.",
