    "无法连接接入服务，请确认手机与电脑的网络、服务地址及端口。局域网调试时需连接同一 Wi-Fi。": "Не удалось подключиться к сервису подключения. Проверьте сети, адрес и порт сервиса. Для локальной разработки подключите оба устройства к одной сети Wi-Fi.",
