    "仅自动读取；其他操作均需先征得你的批准。": "Автоматически только читает; всё остальное сначала требует вашего одобрения.",
    "不中断任务；所有操作和决策均自动进行。": "Не прерывает работу; все действия и решения выполняются автоматически.",
