    "由 AI 审查员批准或拒绝原本需要询问的操作；审查失败只阻止该操作。": "ИИ-проверяющий одобряет или отклоняет каждое действие, которое иначе потребовало бы подтверждения; неудачная проверка блокирует только это действие.",
